 readonly TextBox title=new(){Width=150},duration=new(){Width=65},keyTime=new(){Width=85},positionBox=new(){Width=80};readonly ComboBox lengths=new(){ItemsSource=new[]{"0.5 s","1 s","2 s","5 s","10 s",L.T("직접 입력")},SelectedIndex=2,Width=105},interpolation=new(){ItemsSource=new[]{"Linear","Hold"},SelectedIndex=0,Width=90};
 readonly CheckBox loop=new(){Content=L.T("반복")},autoKey=new(){Content=L.T("자동 기록"),IsChecked=true},follow=new(){Content=L.T("재생 위치 따라가기"),IsChecked=true};readonly TextBlock endTime=new(){Foreground=StudioTheme.Accent,VerticalAlignment=VerticalAlignment.Center},zoomLabel=new(){Foreground=StudioTheme.Muted,VerticalAlignment=VerticalAlignment.Center},selectionLabel=new(){Foreground=StudioTheme.Muted,VerticalAlignment=VerticalAlignment.Center};
 readonly KeyTimeline timeline;readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(33)};readonly Stopwatch clock=new();double anchor,position;bool updating,playing,gesture,active,hasDocument;public bool Dirty{get;private set;}public bool Playing=>playing;public bool Active=>active;public event Action<bool>? ActiveChanged;FacialKey? selected,clipboard;Preset? lastFrame;string? path,saved;
