 public ClipPanel(Action<Preset?> show,Func<Preset> get,Func<IEnumerable<Preset>>? documents=null){display=show;current=get;opened=documents??(()=>new[]{current()});
  var toolbar=new WrapPanel();Children.Add(toolbar);Button(toolbar,"새 클립",()=>{if(Discard())SetClip(new(){Name=L.T("새 클립"),Duration=clip.Duration,Profile=current().Profile},false);});Button(toolbar,"클립 열기",Open);Button(toolbar,"클립 저장",Save);Button(toolbar,"표정 전환 만들기",CreateTransition);
  var metadata=new WrapPanel();Children.Add(metadata);Field(metadata,"클립 이름",title);Field(metadata,"클립 길이",lengths);metadata.Children.Add(duration);duration.ToolTip=L.T("초 단위 직접 입력");
  autoKey.ToolTip=L.T("시간을 선택하고 표정을 바꾸면 움직임이 기록됩니다.");
  var transport=new WrapPanel();Children.Add(transport);Button(transport,"재생 / 일시정지",TogglePlayback);Button(transport,"정지",()=>{Pause();Seek(0);});transport.Children.Add(loop);transport.Children.Add(autoKey);Field(transport,"현재 시간",positionBox);transport.Children.Add(endTime);Button(transport,"실행 취소",Undo);Button(transport,"다시 실행",Redo);
  timeline=new KeyTimeline(()=>clip,()=>position,Seek,t=>AddAt(t,clip.Keys.Count==0?current():clip.Evaluate(t)),SelectKey,()=>history.Begin(clip),()=>{history.Commit(clip);Mark();Refresh();},()=>{var old=history.Cancel();if(old!=null){clip=old;RebindSelection();Mark();Refresh();ShowTime(true);}});Children.Add(timeline);
  var navigation=new WrapPanel();Children.Add(navigation);Button(navigation,"전체 보기",()=>timeline.Fit());navigation.Children.Add(zoomLabel);navigation.Children.Add(follow);navigation.Children.Add(new TextBlock{Text=L.T("Ctrl+클릭: 키 추가 · 휠: 탐색 · Alt+휠: 확대"),FontSize=10,Foreground=StudioTheme.Muted,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,0,0)});timeline.FollowChanged+=value=>{updating=true;follow.IsChecked=value;updating=false;};follow.Click+=(_,_)=>{timeline.FollowPlayback=follow.IsChecked==true;if(timeline.FollowPlayback)timeline.Reveal(position);};timeline.ViewChanged+=()=>zoomLabel.Text=$"{clip.Duration/timeline.Viewport.Span:0.##}× · {timeline.Viewport.Start:0.###}–{timeline.Viewport.End:0.###} s";
  timeline.ToolTip=L.T("휠: 좌우 탐색 · Alt+휠: 확대 · Ctrl+클릭: 키 추가 · Delete: 삭제 · Ctrl+C/V · ↑/↓: 인접 키");
  var properties=new WrapPanel();Children.Add(properties);properties.Children.Add(selectionLabel);Field(properties,"키 시간",keyTime);properties.Children.Add(interpolation);Button(properties,"프리셋 가져오기",Import);Button(properties,"현재 표정 저장",ExportPreset);Children.Remove(properties);Children.Insert(Children.IndexOf(timeline),properties);
  BindEntry(title,()=>CommitName(title.Text));BindEntry(duration,()=>SetDuration(Number(duration)));BindEntry(keyTime,()=>{if(selected!=null)SetSelectedProperties(Number(keyTime),interpolation.SelectedItem as string??"Linear");});BindEntry(positionBox,()=>Seek(Number(positionBox)));
  positionBox.GotKeyboardFocus+=(_,_)=>{Pause();ShowTime(true);};lengths.SelectionChanged+=(_,_)=>{if(updating)return;duration.Visibility=lengths.SelectedIndex==5?Visibility.Visible:Visibility.Collapsed;if(lengths.SelectedIndex==5){duration.Focus();duration.SelectAll();return;}Run(()=>SetDuration(new[]{.5,1,2,5,10}[lengths.SelectedIndex]));};interpolation.SelectionChanged+=(_,_)=>{if(!updating&&selected!=null)Run(()=>SetSelectedProperties(selected.Time,interpolation.SelectedItem as string??"Linear"));};
  timeline.ContextRequested+=(key,time)=>{if(key!=null)SelectKey(key);else Seek(time);var menu=new ContextMenu();void Item(string label,Action action,bool on){var item=new MenuItem{Header=L.T(label),IsEnabled=on};item.Click+=(_,_)=>Run(action);menu.Items.Add(item);}Item("키 복사",CopyKey,key!=null);Item("여기에 붙여넣기",Paste,clipboard!=null);Item("키 삭제",DeleteKey,key!=null);menu.PlacementTarget=timeline;menu.IsOpen=true;};
  timer.Tick+=(_,_)=>{bool ended=false;double t=anchor+clock.Elapsed.TotalSeconds;if(t>=clip.Duration){if(loop.IsChecked==true)t%=clip.Duration;else{t=clip.Duration;Pause();ended=true;}}position=t;ShowTime(ended,true);};Unloaded+=(_,_)=>{Pause();EndMorphEdit(true);};
  PreviewKeyDown+=(_,e)=>{if(Keyboard.FocusedElement is TextBox)return;bool ctrl=(Keyboard.Modifiers&ModifierKeys.Control)!=0;if(ctrl&&e.Key==Key.Z){Undo();e.Handled=true;}else if(ctrl&&e.Key==Key.Y){Redo();e.Handled=true;}else if(timeline.IsKeyboardFocusWithin){if(e.Key==Key.Delete){DeleteKey();e.Handled=true;}else if(ctrl&&e.Key==Key.C){CopyKey();e.Handled=true;}else if(ctrl&&e.Key==Key.V){Paste();e.Handled=true;}}};Refresh();
